				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "curso_id IN (SELECT id FROM cursos WHERE profesor_id = " . intval($_SESSION["profesor_id"]) . ")");
} elseif ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "curso_id IN (SELECT curso_id FROM inscripciones WHERE estudiante_id = " . intval($_SESSION["estudiante_id"]) . ")");
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		if (empty($values["fecha_entrega"])) {
    $values["fecha_entrega"] = date("Y-m-d 23:59:00", strtotime("+7 days"));
}

if (empty(trim($values["titulo"]))) {
    $message = "El título de la tarea es obligatorio.";
    return false;
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



